def run(args):
    p = subprocess.run([sys.executable, T] + args, capture_output=True, text=True, encoding="utf-8")
    out = (p.stdout + p.stderr).strip()
    return p.returncode, out


if __name__ == "__main__":
    only = sys.argv[1] if len(sys.argv) > 1 else "all"
    if only in ("all", "sources"):
        for n, pub, title, off, d in SOURCES:
            rc, out = run(["source", "--name", n, "--publisher", pub, "--title", title, "--official", off, "--page-date", d])
            print("SRC", n, rc, out[-160:])
    if only in ("all", "facts"):
        for n, claim, quote, d, st, note in FACTS:
            a = ["add", "--prefix", "U", "--name", n, "--claim", claim, "--quote", quote, "--page-date", d, "--status", st]
            if note:
                a += ["--note", note]
            rc, out = run(a)
            print(rc, out[-200:].replace("\n", " | "), "<-", claim[:70])
